import type { Needs, WorldObject, Vec2, Inhabitant, Footprint, Affordance, Space } from './types'
// generated by tools/blender/build_room.py, together with public/models/room.glb
import layout from './room-layout.json'
// generated by tools/blender/build_outdoor.py, together with public/models/outdoor.glb
import yardLayout from './yard-layout.json'

export class World {
  /** game minutes since start */
  minutes = 8 * 60
  /** game minutes per real second */
  speed = 10
  readonly objects: WorldObject[] = []
  readonly inhabitants: Inhabitant[] = []
  /** solid geometry for checking whether a body movement has room; unset until the physics engine has loaded */
  space?: Space
  /** how far the house door is open, 0 (shut) .. 1 (open); people open and close it by hand (skills/door.ts) */
  doorOpen = 0
  /** who is using the door right now, so two people do not open and close it at the same time */
  doorUser?: string
  /** objectId -> agent name; sitting/lying objects fit one agent at a time */
  private occupancy = new Map<string, string>()
  /** the house: 10 x 8 m, centred on the origin */
  readonly bounds = { w: layout.room.w, d: layout.room.d }
  /** the fenced yard around the house */
  readonly yard = yardLayout.yard
  /** the gap in the fence, the only way between the yard and the meadow beyond */
  readonly gate = yardLayout.gate
  /** everything agents may walk in: the yard and a strip of meadow east of the fence */
  readonly area = yardLayout.area
  /** glowing things outdoors (campfire, tent lantern): the game lights them after dark */
  readonly lights = yardLayout.lights
  /** the doorway in the right-hand wall, the only way between house and yard */
  readonly door = yardLayout.door
  /** floor areas of all furniture, trees, bushes and so on that block walking */
  readonly obstacles: Footprint[] = [
    ...layout.furniture.flatMap(f => f.footprint ? [f.footprint] : []),
    ...yardLayout.obstacles,
  ]

  // ---- navigation grid: the whole walkable area; house walls and the fence are blocked except at the door and the gate ----
  readonly cell = 0.2
  readonly agentRadius = 0.35
  private nx = Math.round((this.area.x1 - this.area.x0) / this.cell)
  private nz = Math.round((this.area.z1 - this.area.z0) / this.cell)
  private blocked = new Uint8Array(this.nx * this.nz)

  private cx(i: number) { return this.area.x0 + (i + 0.5) * this.cell }
  private cz(j: number) { return this.area.z0 + (j + 0.5) * this.cell }
  private ci(x: number) { return Math.floor((x - this.area.x0) / this.cell) }
  private cj(z: number) { return Math.floor((z - this.area.z0) / this.cell) }

  private buildGrid() {
    const r = this.agentRadius, hw = this.bounds.w / 2, hd = this.bounds.d / 2
    const t = layout.room.wallThickness, y = this.yard, a = this.area, door = this.door, gate = this.gate
    const rail = 0.06 // half thickness of the fence
    for (let j = 0; j < this.nz; j++) for (let i = 0; i < this.nx; i++) {
      const x = this.cx(i), z = this.cz(j)
      // keep clear of the edge of the area
      let b = x < a.x0 + r || x > a.x1 - r || z < a.z0 + r || z > a.z1 - r
      // west of the fence line the yard is bounded by the fence on the other three sides
      if (x < y.x1 && (z < y.z0 + r || z > y.z1 - r)) b = true
      // the right-hand fence, with the gate
      if (Math.abs(x - y.x1) < r + rail && z > y.z0 - r && z < y.z1 + r && Math.abs(z - gate.z) > gate.halfWidth) b = true
      // the house: free inside (clear of the walls), blocked in the wall ring around it
      const ax = Math.abs(x), az = Math.abs(z)
      if (ax <= hw + t + r && az <= hd + t + r && !(ax <= hw - r && az <= hd - r)) b = true
      // ...except through the doorway
      if (x >= hw - r && x <= hw + t + r && Math.abs(z - door.z) <= door.halfWidth) b = false
      for (const f of this.obstacles) {
        if (Math.abs(x - f.cx) < f.w / 2 + r && Math.abs(z - f.cz) < f.d / 2 + r) b = true
      }
      this.blocked[j * this.nx + i] = b ? 1 : 0
    }
  }

  /** centres of blocked cells, for the debug overlay */
  blockedCells(): Vec2[] {
    const out: Vec2[] = []
    for (let j = 0; j < this.nz; j++) for (let i = 0; i < this.nx; i++) if (this.blocked[j * this.nx + i]) out.push({ x: this.cx(i), z: this.cz(j) })
    return out
  }

  isFree(p: Vec2) {
    const i = this.ci(p.x), j = this.cj(p.z)
    return i >= 0 && j >= 0 && i < this.nx && j < this.nz && !this.blocked[j * this.nx + i]
  }

  clearLine(a: Vec2, b: Vec2) {
    const n = Math.ceil(dist(a, b) / (this.cell / 5))
    for (let k = 0; k <= n; k++) {
      const t = n ? k / n : 0
      if (!this.isFree({ x: a.x + (b.x - a.x) * t, z: a.z + (b.z - a.z) * t })) return false
    }
    return true
  }

  /**
   * How far `p` is from the nearest piece of furniture (its footprint) or, inside the house, from a wall.
   * Used for the few steps that leave the grid, such as squeezing along a bed to its side.
   */
  clearance(p: Vec2) {
    let d = Infinity
    for (const f of this.obstacles) {
      const dx = Math.max(0, Math.abs(p.x - f.cx) - f.w / 2), dz = Math.max(0, Math.abs(p.z - f.cz) - f.d / 2)
      d = Math.min(d, Math.hypot(dx, dz))
    }
    const hw = this.bounds.w / 2, hd = this.bounds.d / 2
    if (Math.abs(p.x) < hw && Math.abs(p.z) < hd) d = Math.min(d, hw - Math.abs(p.x), hd - Math.abs(p.z))
    return d
  }

  /** is every point of the segment at least `min` metres from furniture and walls? */
  clearSegment(a: Vec2, b: Vec2, min: number) {
    const n = Math.max(1, Math.ceil(dist(a, b) / 0.05))
    for (let k = 0; k <= n; k++) {
      const t = k / n
      if (this.clearance({ x: a.x + (b.x - a.x) * t, z: a.z + (b.z - a.z) * t }) < min) return false
    }
    return true
  }

  /** nearest free cell to p (BFS outward), for starts/goals that sit inside an obstacle */
  private nearestFree(p: Vec2): [number, number] | null {
    const si = Math.min(this.nx - 1, Math.max(0, this.ci(p.x))), sj = Math.min(this.nz - 1, Math.max(0, this.cj(p.z)))
    const seen = new Set<number>([sj * this.nx + si])
    const q: [number, number][] = [[si, sj]]
    for (let h = 0; h < q.length; h++) {
      const [i, j] = q[h]
      if (!this.blocked[j * this.nx + i]) return [i, j]
      for (const [di, dj] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const ni = i + di, nj = j + dj, key = nj * this.nx + ni
        if (ni >= 0 && nj >= 0 && ni < this.nx && nj < this.nz && !seen.has(key)) { seen.add(key); q.push([ni, nj]) }
      }
    }
    return null
  }

  /**
   * Waypoints from `from` to `to` that avoid furniture and walls (A* on the grid, then line-of-sight
   * simplification). The final point is exactly `to`; `from` is not included.
   */
  findPath(from: Vec2, to: Vec2): Vec2[] {
    return this.route(from, to) ?? [to]
  }

  /**
   * Like findPath, but also keeps clear of the circles in `avoid` (people or things in the way), and returns
   * null when there is no way round them.
   */
  route(from: Vec2, to: Vec2, avoid: { x: number; z: number; r: number }[] = []): Vec2[] | null {
    const s = this.nearestFree(from), g = this.nearestFree(to)
    if (!s || !g) return null
    const inAvoid = (i: number, j: number) => avoid.some(c => Math.hypot(this.cx(i) - c.x, this.cz(j) - c.z) < c.r)
    const N = this.nx * this.nz, key = (i: number, j: number) => j * this.nx + i
    const gScore = new Float32Array(N).fill(Infinity), came = new Int32Array(N).fill(-1), closed = new Uint8Array(N)
    const open: [number, number][] = [] // [f, key]
    const h = (i: number, j: number) => Math.hypot(i - g[0], j - g[1])
    gScore[key(s[0], s[1])] = 0
    open.push([h(s[0], s[1]), key(s[0], s[1])])
    let found = false
    while (open.length) {
      let bi = 0
      for (let k = 1; k < open.length; k++) if (open[k][0] < open[bi][0]) bi = k
      const [, cur] = open.splice(bi, 1)[0]
      if (closed[cur]) continue
      closed[cur] = 1
      const ci = cur % this.nx, cj = Math.floor(cur / this.nx)
      if (ci === g[0] && cj === g[1]) { found = true; break }
      for (let di = -1; di <= 1; di++) for (let dj = -1; dj <= 1; dj++) {
        if (!di && !dj) continue
        const ni = ci + di, nj = cj + dj
        if (ni < 0 || nj < 0 || ni >= this.nx || nj >= this.nz || this.blocked[key(ni, nj)]) continue
        if (avoid.length && inAvoid(ni, nj) && !(ni === g[0] && nj === g[1])) continue
        // no cutting corners between two blocked neighbours
        if (di && dj && (this.blocked[key(ci + di, cj)] || this.blocked[key(ci, cj + dj)])) continue
        const nk = key(ni, nj), ng = gScore[cur] + Math.hypot(di, dj)
        if (ng < gScore[nk]) { gScore[nk] = ng; came[nk] = cur; open.push([ng + h(ni, nj), nk]) }
      }
    }
    if (!found) return null
    const cells: Vec2[] = []
    for (let k = key(g[0], g[1]); k !== -1; k = came[k]) cells.push({ x: this.cx(k % this.nx), z: this.cz(Math.floor(k / this.nx)) })
    cells.reverse()
    // string-pull: keep only the corners we actually need
    const pts: Vec2[] = [from, ...cells, to]
    const out: Vec2[] = []
    let anchor = 0
    const clear = (a: Vec2, b: Vec2) => this.clearLine(a, b) && (!avoid.length || avoid.every(c => segDist(c, a, b) >= c.r))
    while (anchor < pts.length - 1) {
      let far = pts.length - 1
      while (far > anchor + 1 && !clear(pts[anchor], pts[far])) far--
      out.push(pts[far])
      anchor = far
    }
    return out
  }

  constructor() {
    this.objects.push(...(layout.objects as WorldObject[]), ...(yardLayout.objects as WorldObject[]))
    this.buildGrid()
  }

  get hour() { return Math.floor(this.minutes / 60) % 24 }
  get day() { return Math.floor(this.minutes / 1440) + 1 }
  get clock() { return this.format(this.minutes) }
  format(t: number) {
    const day = Math.floor(t / 1440) + 1, h = Math.floor(t / 60) % 24, m = Math.floor(t % 60)
    return `Day ${day} ${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`
  }

  occupant(id: string) { return this.occupancy.get(id) }
  claim(id: string, who: string) { this.occupancy.set(id, who) }
  release(id: string, who: string) { if (this.occupancy.get(id) === who) this.occupancy.delete(id) }

  /** Everyone within earshot (the room is small, so: everyone nearby) hears it. */
  broadcast(from: Inhabitant, text: string, range = 8) {
    for (const i of this.inhabitants) {
      if (i !== from && dist(i.pos, from.pos) <= range) i.hear(from.name, text)
    }
  }

  find(id: string) { return this.objects.find(o => o.id === id) }

  /** Is this point in the lake (and not on the pier)? Agents there swim. */
  inWater(p: Vec2) {
    const w = yardLayout.water, pier = yardLayout.pier
    const dx = (p.x - w.x) / w.rx, dz = (p.z - w.z) / w.rz
    if (dx * dx + dz * dz >= 1) return false
    return !(Math.abs(p.x - pier.x) <= pier.w / 2 && p.z <= pier.z1)
  }

  /** which part of the world a point is in */
  placeOf(p: Vec2): 'house' | 'yard' | 'meadow' {
    const t = layout.room.wallThickness
    if (Math.abs(p.x) < this.bounds.w / 2 + t && Math.abs(p.z) < this.bounds.d / 2 + t) return 'house'
    return p.x > this.yard.x1 ? 'meadow' : 'yard'
  }

  /** Is this activity possible at the current hour? (Some only make sense by day or by night.) */
  isAvailable(aff: Affordance, hour = this.hour) {
    if (!aff.hours) return true
    const [from, to] = aff.hours
    return from < to ? hour >= from && hour < to : hour >= from || hour < to
  }

  advance(realDt: number) {
    const gameDt = realDt * this.speed
    this.minutes += gameDt
    return gameDt
  }

  decayNeeds(needs: Needs, gameMinutes: number) {
    needs.energy = clamp(needs.energy - 0.06 * gameMinutes)
    needs.fun = clamp(needs.fun - 0.08 * gameMinutes)
    needs.knowledge = clamp(needs.knowledge - 0.03 * gameMinutes)
  }
}

export const clamp = (v: number, lo = 0, hi = 100) => Math.min(hi, Math.max(lo, v))
export const dist = (a: Vec2, b: Vec2) => Math.hypot(a.x - b.x, a.z - b.z)
/** distance from point p to the segment a-b */
export function segDist(p: Vec2, a: Vec2, b: Vec2) {
  const vx = b.x - a.x, vz = b.z - a.z, l2 = vx * vx + vz * vz
  const t = l2 ? Math.max(0, Math.min(1, ((p.x - a.x) * vx + (p.z - a.z) * vz) / l2)) : 0
  return Math.hypot(p.x - (a.x + vx * t), p.z - (a.z + vz * t))
}
